public static void display(int spaces, int lines)
{
   if(lines == 0)
      return;
   else
   {
      spaces++;
      for(int x = 0; x < spaces; ++x)
         System.out.print(".");
      System.out.println("O");
      display(spaces, lines - 1);
   }
}

